package com.campus.business.controller;import com.campus.business.common.*;import lombok.RequiredArgsConstructor;import org.springframework.jdbc.core.namedparam.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/operation-logs") @RequiredArgsConstructor @PreAuthorize("hasRole('OWNER')") public class OperationLogController{private final NamedParameterJdbcTemplate jdbc;@GetMapping public ApiResponse<PageResult<Map<String,Object>>> list(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int pageSize,@RequestParam(required=false)String module,@RequestParam(required=false)String keyword){StringBuilder w=new StringBuilder(" WHERE 1=1");MapSqlParameterSource p=new MapSqlParameterSource();if(module!=null&&!module.isBlank()){w.append(" AND module=:module");p.addValue("module",module);}if(keyword!=null&&!keyword.isBlank()){w.append(" AND (operator_name LIKE :kw OR operation_description LIKE :kw)");p.addValue("kw","%"+keyword+"%");}long total=jdbc.queryForObject("SELECT COUNT(*) FROM operation_log"+w,p,Long.class);p.addValue("offset",(page-1)*pageSize).addValue("size",pageSize);return ApiResponse.ok(new PageResult<>(jdbc.queryForList("SELECT id,operator_name operatorName,module,operation_type operationType,target_id targetId,operation_description operationDescription,ip_address ipAddress,created_at createdAt FROM operation_log"+w+" ORDER BY created_at DESC LIMIT :offset,:size",p),total,page,pageSize));}}
